49	/**
50	 * Resolves the path to the ripgrep binary, either bundled or system-level.
51	 * Validates system binaries against trusted directories to prevent RCE.
52	 */
53	export async function resolveRipgrepPath(): Promise<string | null> {
54	  try {
55	    const platform = os.platform();
56	    const arch = os.arch();
57	
58	    // Map to the correct bundled binary
59	    const binName = `rg-${platform}-${arch}${platform === 'win32' ? '.exe' : ''}`;
60	
61	    const candidatePaths = [
62	      // 1. SEA runtime layout: everything is flattened into the root dir
63	      path.resolve(__dirname, 'vendor/ripgrep', binName),
64	      // 2. Dev/Dist layout: packages/core/dist/tools/ripGrep.js -> packages/core/vendor/ripgrep
65	      path.resolve(__dirname, '../../vendor/ripgrep', binName),
66	    ];
67	
68	    for (const candidate of candidatePaths) {
69	      if (await fileExists(candidate)) {
70	        return candidate;
71	      }
72	    }
73	
74	    // 3. Fallback: check system PATH
75	    const systemRg = resolveExecutable('rg');
76	    if (systemRg) {
77	      // Security: Validate the system executable to prevent Search Path Interruption.
78	      const realPath = resolveToRealPath(systemRg);
79	
80	      if (isTrustedSystemPath(realPath)) {
81	        // Return absolute path to prevent re-resolution risk.
82	        return realPath;
83	      }
84	    }
85	
86	    return null;
87	  } catch (error: unknown) {
88	    debugLogger.error('Error resolving ripgrep path:', error);
89	    return null;
90	  }
91	}
